import{_ as s,o as e,c as i,a2 as t}from"./chunks/framework.1lnE8eph.js";const k=JSON.parse('{"title":"Source-workspace quick start","description":"","frontmatter":{},"headers":[],"relativePath":"quick-start.md","filePath":"quick-start.md"}'),n={name:"quick-start.md"};function o(p,a,l,r,c,d){return e(),i("div",null,[...a[0]||(a[0]=[t(`<h1 id="source-workspace-quick-start" tabindex="-1">Source-workspace quick start <a class="header-anchor" href="#source-workspace-quick-start" aria-label="Permalink to &quot;Source-workspace quick start&quot;">​</a></h1><p>This is the supported development path for the Bus Map application. The application, table, and pane-resizing package are Yarn workspaces in one source checkout; consumers do not install registry packages or build tarballs for this workflow.</p><h2 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h2><ul><li>Node.js <code>24.13.0</code> from the repository&#39;s <code>.nvmrc</code>.</li><li>Yarn <code>1.22.22</code>.</li><li>The workspace&#39;s required dependencies, already present or available through the team&#39;s approved registry or local cache.</li></ul><p>The workspace includes private Lego packages. Follow the repository owner&#39;s approved dependency access process; this guide does not claim that a clean install works without external registry access.</p><h2 id="install-and-run" tabindex="-1">Install and run <a class="header-anchor" href="#install-and-run" aria-label="Permalink to &quot;Install and run&quot;">​</a></h2><p>From the repository root, which contains <code>app/</code>, <code>modules/</code>, <code>packages/</code>, and the root <code>package.json</code>:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">yarn</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">yarn</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span></span></code></pre></div><p>The package manager resolves <code>@busmap/table</code> to <code>packages/table</code> and <code>@busmap/module-resizing</code> to <code>packages/module-resizing</code>. The application build compiles their workspace source and CSS. Do not run <code>npm install @busmap/table</code>, <code>npm pack</code>, or a separate package distribution build for this path.</p><h2 id="validate" tabindex="-1">Validate <a class="header-anchor" href="#validate" aria-label="Permalink to &quot;Validate&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">yarn</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">yarn</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> validate</span></span></code></pre></div><p><code>yarn validate</code> runs the existing workspace build, package tests, architecture checks, lint, and typechecks. Browser-only checks that require a local browser/CDP endpoint remain separate; see the <a href="/bus-map-pages/docs/validation">validation guide</a>.</p><h2 id="documentation" tabindex="-1">Documentation <a class="header-anchor" href="#documentation" aria-label="Permalink to &quot;Documentation&quot;">​</a></h2><p>Run the documentation site from the same workspace:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">yarn</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> workspace</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @busmap/app</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:dev</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">yarn</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> workspace</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @busmap/app</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:build</span></span></code></pre></div><p>To build for a subpath deployment, set <code>DOCS_BASE_PATH</code> to the actual path, including its leading and trailing slashes, for example:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">DOCS_BASE_PATH</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/bus-map-gantt-docs/</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> yarn</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> workspace</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @busmap/app</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:build</span></span></code></pre></div><p>The standalone table&#39;s <a href="/bus-map-pages/docs/table/guide/getting-started">registry/tarball guide</a> documents a separate distribution workflow; it is not the application source-workspace quick start.</p>`,18)])])}const u=s(n,[["render",o]]);export{k as __pageData,u as default};
